/* From Uiverse.io by JaydipPrajapati1910 - Tags: animation, input */
.__UIV_SCOPE__ .input {
  max-width: 190px;
  border: none;
  outline: none;
  background: none;
  font-size: 18px;
  color: #222;
  padding: 15px 5px 10px 20px;
  box-shadow: Inset 0 1px 25px rgba(0, 0, 0, 0.55);
  border-radius: 25px;
}

.__UIV_SCOPE__ .input:focus {
  border: 2px solid #c3c6ce;
}

.__UIV_SCOPE__ .input::placeholder {
  color: #555;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .input:focus::placeholder {
  color: #999;
}
